//! The data of the game embedded in the application, generated by `tools/game-data` (see
//! `docs/game-data.md`): the stats of each modifier line, with their trade ids, and the English
//! string of a line in another language; the category and the tags of each base; the tiers of
//! the prefixes and suffixes; the templates of the stats of the trade site as a second lookup;
//! the rolls of a unique copied without ranges, from the modifiers of the price database.
//!
//! It reads the lines of every copied item: like the parser, it must never panic, and the
//! lints below rule out what can panic outside the tests.
#![cfg_attr(
    not(test),
    deny(
        clippy::indexing_slicing,
        clippy::string_slice,
        clippy::unwrap_used,
        clippy::expect_used,
        clippy::panic,
        clippy::unreachable,
        clippy::todo,
        clippy::unimplemented
    )
)]

mod bases;
mod lines;
mod modifiers;
mod stats;
mod trade_site;
mod unique_rolls;

pub use bases::{Category, category, trade_category};
#[cfg(test)]
pub use lines::equipment_strings;
pub use lines::{LineMatch, StatMatch, StatSource, english_string, modifier_stats};
pub use modifiers::{AffixLimits, Currency, Tier, modifier_tiers, with_trade_tiers};
pub use stats::TradeGroup;
pub use trade_site::TradeStats;
#[cfg(test)]
pub use trade_site::tests::trade_stats;
pub use unique_rolls::with_unique_rolls;

/// Whether the stat of the game id `id` (`base_maximum_life`) in the game data of `language`
/// has the other sign on the trade site; none when no stat has this id.
#[cfg(test)]
#[must_use]
pub fn stat_inverted(language: crate::language::Language, id: &str) -> Option<bool> {
    stats::Stats::of(language)
        .by_id(id)
        .map(|stat| stat.inverted)
}
